    const expiresAt = Date.now() + (7 * 24 * 60 * 60 * 1000);
    await ctx.db.insert('sessions', { userId: user._id, token, expiresAt, createdAt: Date.now() });

    await ctx.db.patch(user._id, { lastActiveAt: Date.now(), updatedAt: Date.now() });

    return {
      userId: user._id,
      sessionToken: token,
      expiresAt,
      email: user.email,
      name: user.name,
      preferredLanguage: user.preferredLanguage,
      entitlementActive: user.entitlementActive
    };
  }
