interface AuthState {
  userId: Id<'users'> | null;
  sessionToken: string | null;
  sessionExpiresAt: number | null;
  setAuthUser: (data: { userId: Id<'users'>; sessionToken: string; expiresAt: number }) => void;
  signOut: () => void;
  isSessionValid: () => boolean;
}

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      userId: null,
      sessionToken: null,
      sessionExpiresAt: null,
      setAuthUser: ({ userId, sessionToken, expiresAt }) => {
        set({ userId, sessionToken, sessionExpiresAt: expiresAt });
        useUserStore.getState().initializeForUser(userId);
      },
      signOut: () => {
        useUserStore.getState().clearUserData();
        set({ userId: null, sessionToken: null, sessionExpiresAt: null });
      },
      isSessionValid: () => {
        const { sessionExpiresAt } = get();
        return sessionExpiresAt ? Date.now() < sessionExpiresAt : false;
      }
    }),
    { name: 'auth-storage', storage: createJSONStorage(() => AsyncStorage) }
  )
);

