// Force reset password - INTERNAL ONLY, requires admin verification
export const resetUserPassword = internalMutation({
  args: {
    performedByAdminId: v.id('adminUsers'),
    email: v.string(),
    newPassword: v.string()
  },
  handler: async (ctx, args) => {
    // Verify performer is admin
    const performer = await ctx.db.get(args.performedByAdminId);
    if (!performer || performer.role !== 'admin') {
      throw new Error('Only admins can force reset passwords');
    }

    const user = await ctx.db
      .query('users')
      .withIndex('by_email', q => q.eq('email', args.email))
      .first();

    if (!user) {
      throw new Error('User not found');
    }

    // Validate password strength
    if (args.newPassword.length < 8) {
      throw new Error('Password must be at least 8 characters');
    }

    const passwordHash = await bcrypt.hash(args.newPassword, 10);

    await ctx.db.patch(user._id, {
      passwordHash,
      updatedAt: Date.now()
    });

    // Invalidate all existing sessions for this user
    const sessions = await ctx.db
      .query('sessions')
      .withIndex('by_user', q => q.eq('userId', user._id))
      .collect();

    for (const session of sessions) {
      await ctx.db.delete(session._id);
    }

    // Log the action
    await ctx.db.insert('auditLog', {
      entityType: 'user',
      entityId: user._id,
      action: 'update',
      description: `Password force reset for: ${args.email}`,
      performedBy: args.performedByAdminId,
      performedAt: Date.now()
    });

    return true;
  }
});

