// convex/lib/rateLimit.ts
import { MutationCtx } from '../_generated/server';

interface RateLimitConfig {
  maxAttempts: number;
  windowMs: number;
  blockDurationMs: number;
}

const RATE_LIMITS: Record<string, RateLimitConfig> = {
  'login': { maxAttempts: 5, windowMs: 15 * 60 * 1000, blockDurationMs: 30 * 60 * 1000 },
  'signup': { maxAttempts: 3, windowMs: 60 * 60 * 1000, blockDurationMs: 60 * 60 * 1000 },
  'password_reset': { maxAttempts: 3, windowMs: 60 * 60 * 1000, blockDurationMs: 60 * 60 * 1000 },
  'password_reset_verify': { maxAttempts: 5, windowMs: 30 * 60 * 1000, blockDurationMs: 60 * 60 * 1000 }
};

export async function checkRateLimit(
  ctx: MutationCtx,
  key: string,
  action: string
): Promise<{ allowed: boolean; retryAfter?: number }> {
  const config = RATE_LIMITS[action];
  if (!config) return { allowed: true };

  const now = Date.now();
  const record = await ctx.db
    .query('rateLimits')
    .withIndex('by_key_action', q => q.eq('key', key).eq('action', action))
    .first();

  // Check if blocked
  if (record?.blockedUntil && now < record.blockedUntil) {
    return { allowed: false, retryAfter: record.blockedUntil - now };
  }

  // Check if within window
  if (record && now - record.windowStart < config.windowMs) {
    if (record.count >= config.maxAttempts) {
      // Block the user
      await ctx.db.patch(record._id, {
        blockedUntil: now + config.blockDurationMs
      });
      return { allowed: false, retryAfter: config.blockDurationMs };
    }
    // Increment count
    await ctx.db.patch(record._id, { count: record.count + 1 });
  } else {
    // Start new window
    if (record) {
      await ctx.db.patch(record._id, {
        count: 1,
        windowStart: now,
        blockedUntil: undefined
      });
    } else {
      await ctx.db.insert('rateLimits', {
        key,
        action,
        count: 1,
        windowStart: now
      });
    }
  }

  return { allowed: true };
}

