export const verifyResetToken = mutation({
  args: { email: v.string(), token: v.string() },
  handler: async (ctx, args) => {
    const user = await ctx.db
      .query('users')
      .withIndex('by_email', q => q.eq('email', args.email))
      .first();

    if (!user) {
      return { valid: false, error: 'Invalid token' };
    }

    // Check attempt limit
    if ((user.resetAttempts || 0) >= 5) {
      // Invalidate token after 5 failed attempts
      await ctx.db.patch(user._id, {
        resetToken: undefined,
        resetTokenExpiresAt: undefined,
        resetAttempts: undefined
      });
      return { valid: false, error: 'Too many attempts. Request a new code.' };
    }

    // Increment attempts
    await ctx.db.patch(user._id, {
      resetAttempts: (user.resetAttempts || 0) + 1
    });

    if (!user.resetToken || user.resetToken !== args.token) {
      return { valid: false, error: 'Invalid token' };
    }

    if (!user.resetTokenExpiresAt || Date.now() > user.resetTokenExpiresAt) {
      return { valid: false, error: 'Token expired' };
    }

    return { valid: true };
  }
});

