// convex/lib/validation.ts

export const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
export const PHONE_REGEX = /^\+?[1-9]\d{6,14}$/;

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

export function validateEmail(email: string): ValidationResult {
  const errors: string[] = [];
  if (!email || email.length === 0) {
    errors.push('Email is required');
  } else if (email.length > 254) {
    errors.push('Email too long');
  } else if (!EMAIL_REGEX.test(email)) {
    errors.push('Invalid email format');
  }
  return { valid: errors.length === 0, errors };
}

export function validatePassword(password: string): ValidationResult {
  const errors: string[] = [];
  if (!password || password.length < 8) {
    errors.push('Password must be at least 8 characters');
  }
  if (password.length > 128) {
    errors.push('Password too long');
  }
  if (!/[A-Z]/.test(password)) {
    errors.push('Password must contain at least one uppercase letter');
  }
  if (!/[a-z]/.test(password)) {
    errors.push('Password must contain at least one lowercase letter');
  }
  if (!/[0-9]/.test(password)) {
    errors.push('Password must contain at least one number');
  }
  return { valid: errors.length === 0, errors };
}

export function validatePhone(phone: string): ValidationResult {
  const errors: string[] = [];
  if (phone && !PHONE_REGEX.test(phone.replace(/[\s-]/g, ''))) {
    errors.push('Invalid phone number format');
  }
  return { valid: errors.length === 0, errors };
}

export function validateStringLength(value: string, fieldName: string, min: number, max: number): ValidationResult {
  const errors: string[] = [];
  if (value.length < min) {
    errors.push(`${fieldName} must be at least ${min} characters`);
  }
  if (value.length > max) {
    errors.push(`${fieldName} must be at most ${max} characters`);
  }
  return { valid: errors.length === 0, errors };
}

