export const signUp = mutation({
  args: {
    email: v.string(),
    password: v.string(),
    name: v.optional(v.string()),
    preferredLanguage: v.optional(v.union(v.literal('en'), v.literal('ro'), v.literal('it')))
  },
  handler: async (ctx, args) => {
    // Validate email
    const emailValidation = validateEmail(args.email);
    if (!emailValidation.valid) {
      throw new ConvexError(emailValidation.errors.join(', '));
    }

    // Validate password
    const passwordValidation = validatePassword(args.password);
    if (!passwordValidation.valid) {
      throw new ConvexError(passwordValidation.errors.join(', '));
    }

    // Validate name if provided
    if (args.name) {
      const nameValidation = validateStringLength(args.name, 'Name', 1, 100);
      if (!nameValidation.valid) {
        throw new ConvexError(nameValidation.errors.join(', '));
      }
    }

    // Normalize email
    const normalizedEmail = args.email.toLowerCase().trim();

    // Check if user exists
    const existing = await ctx.db
      .query('users')
      .withIndex('by_email', q => q.eq('email', normalizedEmail))
      .first();

    if (existing) {
      throw new ConvexError('User already exists');
    }

    const passwordHash = await bcrypt.hash(args.password, 10);
    const now = Date.now();

    const userId = await ctx.db.insert('users', {
      email: normalizedEmail,
      passwordHash,
      name: args.name?.trim(),
      entitlementActive: false,
      preferredLanguage: args.preferredLanguage || 'en',
      createdAt: now,
      updatedAt: now
    });

    return { userId };
  }
});

