export const listBooks = query({
  args: {
    status: v.optional(v.union(v.literal('draft'), v.literal('ready'), v.literal('published'))),
    categoryId: v.optional(v.id('categories')),
    search: v.optional(v.string()),
    limit: v.optional(v.number()),
    cursor: v.optional(v.string()) // Use cursor-based pagination
  },
  handler: async (ctx, args) => {
    const limit = Math.min(args.limit || 20, 100); // Cap at 100

    let query = ctx.db.query('books');

    // Use index for status filtering
    if (args.status) {
      query = query.withIndex('by_status', q => q.eq('status', args.status));
    }

    // Apply cursor if provided
    let books;
    if (args.cursor) {
      const cursorData = JSON.parse(atob(args.cursor));
      books = await query
        .filter(q => q.lt(q.field('updatedAt'), cursorData.updatedAt))
        .order('desc')
        .take(limit + 1);
    } else {
      books = await query.order('desc').take(limit + 1);
    }

    // Filter by category in memory (for combined filters)
    if (args.categoryId) {
      books = books.filter(b => b.categoryId === args.categoryId);
    }

    // Search filter (consider full-text search for scale)
    if (args.search) {
      const searchLower = args.search.toLowerCase();
      books = books.filter(book =>
        book.cover.title_en.toLowerCase().includes(searchLower) ||
        book.cover.title_ro.toLowerCase().includes(searchLower) ||
        book.cover.title_it.toLowerCase().includes(searchLower) ||
        book.bookKey.toLowerCase().includes(searchLower)
      );
    }

    const hasMore = books.length > limit;
    if (hasMore) books = books.slice(0, limit);

    // Batch category lookups
    const categoryIds = [...new Set(books.map(b => b.categoryId))];
    const categories = await Promise.all(categoryIds.map(id => ctx.db.get(id)));
    const categoryMap = new Map(categories.filter(Boolean).map(c => [c!._id, c]));

    const enrichedBooks = books.map(book => ({
      ...book,
      category: categoryMap.get(book.categoryId) || null
    }));

    // Generate cursor for next page
    const nextCursor = hasMore && books.length > 0
      ? btoa(JSON.stringify({ updatedAt: books[books.length - 1].updatedAt }))
      : null;

    return {
      books: enrichedBooks,
      nextCursor,
      hasMore
    };
  }
});

