'use client';

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { Id } from '@convex/_generated/dataModel';

interface AdminAuthState {
  sessionToken: string | null;
  isLoading: boolean;
}

interface AdminAuthActions {
  setSession: (token: string) => void;
  clearSession: () => void;
  setLoading: (loading: boolean) => void;
}

export const useAuthStore = create<AdminAuthState & AdminAuthActions>()(
  persist(
    (set) => ({
      sessionToken: null,
      isLoading: true,
      setSession: (token) => set({ sessionToken: token, isLoading: false }),
      clearSession: () => set({ sessionToken: null, isLoading: false }),
      setLoading: (loading) => set({ isLoading: loading })
    }),
    {
      name: 'admin-auth-storage',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({ sessionToken: state.sessionToken }),
      onRehydrateStorage: () => (state) => state?.setLoading(false)
    }
  )
);

// Hook that fetches user data from server
export function useAuth() {
  const { sessionToken, clearSession, setSession, isLoading } = useAuthStore();
  const adminQuery = useQuery(api.admin.getCurrentAdminBySession, 
    sessionToken ? { sessionToken } : 'skip'
  );

  return {
    sessionToken,
    isLoading: isLoading || adminQuery === undefined,
    isAuthenticated: !!adminQuery,
    user: adminQuery,
    role: adminQuery?.role, // Role comes from SERVER, not localStorage
    isAdmin: adminQuery?.role === 'admin',
    isEditor: adminQuery?.role === 'editor',
    login: async (loginMutation: Function, email: string, password: string) => {
      const result = await loginMutation({ email, password });
      setSession(result.sessionToken);
      return result;
    },
    logout: () => clearSession()
  };
}

