          console.log(`Purchase retry ${attempt}:`, error.message);
        }
      }
    );

    if (customerInfo?.entitlements.active['premium']) {
      router.replace('/');
    }
  } catch (error: any) {
    if (error.userCancelled) return;

    Alert.alert(
      t.purchaseError,
      t.purchaseErrorDesc,
      [
        { text: t.retry, onPress: handlePurchase },
        { text: t.cancel, style: 'cancel' }
      ]
    );
  } finally {
    setPurchasing(false);
  }
}

