// convex/crons.ts
import { cronJobs } from 'convex/server';
import { internal } from './_generated/api';

const crons = cronJobs();

// Run cleanup daily at 3 AM
crons.daily(
  'cleanup old records',
  { hourUTC: 3, minuteUTC: 0 },
  internal.maintenance.cleanupOldRecords
);

export default crons;

// convex/maintenance.ts
export const cleanupOldRecords = internalMutation({
  handler: async (ctx) => {
    const thirtyDaysAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
    const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);

    // Clean up old subscription events (keep 90 days)
    const oldEvents = await ctx.db
      .query('subscriptionEvents')
      .filter(q => q.lt(q.field('processedAt'), ninetyDaysAgo))
      .take(100);

    for (const event of oldEvents) {
      await ctx.db.delete(event._id);
    }

    // Clean up old audit logs (keep 90 days)
    const oldLogs = await ctx.db
      .query('auditLog')
      .filter(q => q.lt(q.field('performedAt'), ninetyDaysAgo))
      .take(100);

    for (const log of oldLogs) {
      await ctx.db.delete(log._id);
    }

    // Clean up expired sessions (keep 7 days past expiry)
    const expiredSessions = await ctx.db
      .query('sessions')
      .filter(q => q.lt(q.field('expiresAt'), thirtyDaysAgo))
      .take(100);

    for (const session of expiredSessions) {
      await ctx.db.delete(session._id);
    }

    // Clean up old rate limit records
    const oldRateLimits = await ctx.db
      .query('rateLimits')
      .filter(q => q.lt(q.field('windowStart'), thirtyDaysAgo))
      .take(100);

    for (const record of oldRateLimits) {
      await ctx.db.delete(record._id);
    }

    return {
      deletedEvents: oldEvents.length,
      deletedLogs: oldLogs.length,
      deletedSessions: expiredSessions.length,
      deletedRateLimits: oldRateLimits.length
    };
  }
});

